import {initializeApp} from "firebase/app";
import {getFirestore,connectFirestoreEmulator,writeBatch,doc} from "firebase/firestore";
const app=initializeApp({projectId:"demo-reading-club"});
const db=getFirestore(app);connectFirestoreEmulator(db,"127.0.0.1",8080);
const batch=writeBatch(db);
batch.set(doc(db,"books","seed-story"),{title:"Seed Story",pages:20});
batch.set(doc(db,"books","rain-story"),{title:"Rain Story",pages:24});
await batch.commit();
